SELECT p.id, p.name, p.url, p.thumbnailUrl, p.picWidth, p.picHeight, p.categoryId, c.name AS categoryName, p.spaceId, p.userId, p.tags, p.reviewStatus, p.createTime, COALESCE(ps.likeCount, 0) AS likeCount, COALESCE(ps.favoriteCount, 0) AS favoriteCount, COALESCE(ps.shareCount, 0) AS shareCount, COALESCE(ps.viewCount, 0) AS viewCount, COALESCE(ps.downloadCount, 0) AS downloadCount FROM picture p LEFT JOIN picture_statistics ps ON p.id = ps.pictureId LEFT JOIN category c ON p.categoryId = c.id WHERE p.id IN
#{id}
AND p.isDelete = 0

mapper.update:
UPDATE picture SET hotScore = CASE id

    WHEN #{item.id} THEN #{item.score}

END
WHERE id IN

    #{item.id}
